CREATE DATABASE IF NOT EXISTS autonomous_fleet; USE autonomous_fleet;
CREATE TABLE users(user_id INT AUTO_INCREMENT PRIMARY KEY, full_name VARCHAR(100) NOT NULL, email VARCHAR(150) UNIQUE NOT NULL, role ENUM('FLEET_MANAGER','VEHICLE_OPERATOR','MAINTENANCE_TECHNICIAN') NOT NULL);
CREATE TABLE vehicles(vehicle_id INT AUTO_INCREMENT PRIMARY KEY, vehicle_code VARCHAR(30) UNIQUE NOT NULL, status ENUM('ACTIVE','IDLE','WARNING','MAINTENANCE') NOT NULL DEFAULT 'IDLE', battery_percent TINYINT UNSIGNED NOT NULL DEFAULT 100, health_status VARCHAR(40) NOT NULL DEFAULT 'Normal', current_location VARCHAR(150), updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE routes(route_id INT AUTO_INCREMENT PRIMARY KEY, vehicle_id INT, origin VARCHAR(150) NOT NULL, destination VARCHAR(150) NOT NULL, estimated_minutes INT, route_status VARCHAR(30) DEFAULT 'PLANNED', FOREIGN KEY(vehicle_id) REFERENCES vehicles(vehicle_id) ON DELETE SET NULL);
CREATE TABLE maintenance(maintenance_id INT AUTO_INCREMENT PRIMARY KEY, vehicle_id INT NOT NULL, issue_description VARCHAR(255) NOT NULL, priority ENUM('LOW','MEDIUM','HIGH','CRITICAL') DEFAULT 'MEDIUM', repair_status ENUM('OPEN','IN_PROGRESS','RESOLVED') DEFAULT 'OPEN', scheduled_date DATE, assigned_technician INT, FOREIGN KEY(vehicle_id) REFERENCES vehicles(vehicle_id), FOREIGN KEY(assigned_technician) REFERENCES users(user_id) ON DELETE SET NULL);
CREATE TABLE alerts(alert_id INT AUTO_INCREMENT PRIMARY KEY, vehicle_id INT NOT NULL, alert_type VARCHAR(80) NOT NULL, severity ENUM('INFO','WARNING','CRITICAL') DEFAULT 'WARNING', message VARCHAR(255) NOT NULL, is_resolved BOOLEAN DEFAULT FALSE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(vehicle_id) REFERENCES vehicles(vehicle_id));
